package logger

import (
	"bytes"
	"errors"
	"io"
	"os"
	"sync"
	"testing"
)

func TestNewLogger(t *testing.T) {
	l := NewLogger()
	if l == nil {
		t.Fatal("expected non-nil logger")
	}
	if l.Out != os.Stderr {
		t.Error("expected default Out to be os.Stderr")
	}
}

func TestFunLogger_Info(t *testing.T) {
	var buf bytes.Buffer
	l := NewLogger()
	l.Out = &buf
	l.Info("hello %s", "world")
	if got := buf.String(); got != "hello world\n" {
		t.Errorf("got %q, want %q", got, "hello world\n")
	}
}

func TestFunLogger_Check_Warning_Error(t *testing.T) {
	l := NewLogger()
	l.Out = io.Discard
	l.Check("checked %d", 1)
	l.Warning("warn %d", 2)
	l.Error(errors.New("fail"))
	// visually inspect output or redirect os.Stdout/os.Stderr if needed
}

func TestFunLogger_Loading(t *testing.T) {
	l := NewLogger()
	l.Out = io.Discard
	l.Wg = &sync.WaitGroup{}
	l.Done = make(chan struct{})
	l.Fail = make(chan struct{})
	l.Wg.Add(1)
	go l.Loading("loading test")
	l.Done <- struct{}{}
	l.Wg.Wait()
}

package adm

import (
	"testing"

	"github.com/NVIDIA/kubectl-nv/internal/logger"
)

func TestNewCommand(t *testing.T) {
	log := logger.NewLogger()
	cmd := NewCommand(log)
	if cmd == nil {
		t.Fatal("expected non-nil command")
	}
	if cmd.Name != "adm" {
		t.Errorf("expected command name 'adm', got '%s'", cmd.Name)
	}
	if len(cmd.Subcommands) == 0 {
		t.Error("expected at least one subcommand")
	}
}

package mustgather

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/NVIDIA/kubectl-nv/internal/logger"
)

func TestNewCommand(t *testing.T) {
	log := logger.NewLogger()
	cmd := NewCommand(log)
	if cmd == nil {
		t.Fatal("expected non-nil command")
	}
	if cmd.Name != "must-gather" {
		t.Errorf("expected command name 'must-gather', got '%s'", cmd.Name)
	}
	if len(cmd.Flags) == 0 {
		t.Error("expected flags to be set")
	}
}

func TestNewGatherer(t *testing.T) {
	dir := t.TempDir()
	opts := &Options{ArtifactDir: dir, Kubeconfig: "/dev/null"}
	g, err := NewGatherer(opts)
	if err == nil {
		g.Close()
	}
	// Should fail due to invalid kubeconfig
	if err == nil {
		t.Error("expected error for invalid kubeconfig")
	}

	// Valid directory, but log file creation error
	badDir := filepath.Join(dir, "notexist", string([]byte{0}))
	opts2 := &Options{ArtifactDir: badDir, Kubeconfig: "/dev/null"}
	_, err2 := NewGatherer(opts2)
	if err2 == nil {
		t.Error("expected error for bad artifact dir")
	}
}

func TestWriteStringToFile(t *testing.T) {
	f, err := os.CreateTemp("", "testfile")
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() { os.Remove(f.Name()) })
	err = writeStringToFile(f, "hello")
	if err != nil {
		t.Errorf("unexpected error: %v", err)
	}
	f.Close()
	// Test error case: closed file
	f2, _ := os.CreateTemp("", "testfile2")
	f2.Close()
	err = writeStringToFile(f2, "fail")
	if err == nil {
		t.Error("expected error writing to closed file")
	}
}

package mustgather

import (
	"os"
	"testing"

	"k8s.io/client-go/rest"
)

func TestGetKubeconfigPath(t *testing.T) {
	tempFile, err := os.CreateTemp("", "kubeconfig")
	if err != nil {
		t.Fatal(err)
	}
	defer os.Remove(tempFile.Name())

	cases := []struct {
		name    string
		input   string
		setEnv  bool
		envVal  string
		want    string
		wantErr bool
	}{
		{"file exists", tempFile.Name(), false, "", tempFile.Name(), false},
		{"env set", "notfound", true, tempFile.Name(), tempFile.Name(), false},
		{"not found", "notfound", false, "", "", true},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			if c.setEnv {
				t.Setenv("KUBECONFIG", c.envVal)
			} else {
				os.Unsetenv("KUBECONFIG")
			}
			got, err := getKubeconfigPath(c.input)
			if (err != nil) != c.wantErr {
				t.Errorf("err = %v, wantErr %v", err, c.wantErr)
			}
			if !c.wantErr && got != c.want {
				t.Errorf("got %q, want %q", got, c.want)
			}
		})
	}
}

func TestCreateKubernetesClient(t *testing.T) {
	tempFile, err := os.CreateTemp("", "kubeconfig")
	if err != nil {
		t.Fatal(err)
	}
	defer os.Remove(tempFile.Name())
	_, err = createKubernetesClient(tempFile.Name())
	if err == nil {
		t.Error("expected error for empty kubeconfig")
	}
}

func TestSetKubernetesDefaults(t *testing.T) {
	cfg := &rest.Config{}
	err := setKubernetesDefaults(cfg)
	if err != nil {
		t.Errorf("unexpected error: %v", err)
	}
	if cfg.APIPath != "/api" {
		t.Error("APIPath not set")
	}
	if cfg.GroupVersion == nil || cfg.GroupVersion.Version != "v1" {
		t.Error("GroupVersion not set")
	}
}

package mustgather

import (
	"path/filepath"
	"reflect"
	"testing"

	"k8s.io/cli-runtime/pkg/genericiooptions"
)

func TestNewCopyOptions(t *testing.T) {
	ioStreams := genericiooptions.IOStreams{}
	opt := NewCopyOptions(ioStreams)
	if opt == nil {
		t.Fatal("expected non-nil CopyOptions")
	}
	if opt.IOStreams != ioStreams {
		t.Error("IOStreams not set correctly")
	}
}

func TestExtractFileSpec(t *testing.T) {
	cases := []struct {
		name    string
		arg     string
		want    fileSpec
		wantErr bool
	}{
		{"local path", "/tmp/foo", fileSpec{File: newLocalPath("/tmp/foo")}, false},
		{"pod:file", "pod1:/etc/passwd", fileSpec{PodName: "pod1", File: newRemotePath("/etc/passwd")}, false},
		{"ns/pod:file", "ns1/pod2:/etc/passwd", fileSpec{PodNamespace: "ns1", PodName: "pod2", File: newRemotePath("/etc/passwd")}, false},
		{"bad format", ":/etc/passwd", fileSpec{}, true},
		{"too many slashes", "a/b/c:/foo", fileSpec{}, true},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			got, err := extractFileSpec(c.arg)
			if (err != nil) != c.wantErr {
				t.Errorf("err = %v, wantErr %v", err, c.wantErr)
			}
			if !c.wantErr && !reflect.DeepEqual(got, c.want) {
				t.Errorf("got %+v, want %+v", got, c.want)
			}
		})
	}
}

func TestLocalPathHelpers(t *testing.T) {
	p := newLocalPath("/tmp/foo/bar.txt")
	if p.Dir().String() != filepath.Dir("/tmp/foo/bar.txt") {
		t.Error("Dir() failed")
	}
	if p.Base().String() != filepath.Base("/tmp/foo/bar.txt") {
		t.Error("Base() failed")
	}
	if p.Clean().String() != filepath.Clean("/tmp/foo/bar.txt") {
		t.Error("Clean() failed")
	}
	joined := p.Join(newLocalPath("baz.txt"))
	if joined.String() != filepath.Join("/tmp/foo/bar.txt", "baz.txt") {
		t.Error("Join() failed")
	}
}

func TestRemotePathHelpers(t *testing.T) {
	p := newRemotePath("/foo/bar.txt")
	if p.Dir().String() != "/foo" {
		t.Error("Dir() failed")
	}
	if p.Base().String() != "bar.txt" {
		t.Error("Base() failed")
	}
	if p.Clean().String() != "/foo/bar.txt" {
		t.Error("Clean() failed")
	}
	joined := p.Join(newRemotePath("baz.txt"))
	if joined.String() != "/foo/bar.txt/baz.txt" {
		t.Error("Join() failed")
	}
}

func TestIsRelative(t *testing.T) {
	base := newLocalPath("/tmp/foo")
	target := newLocalPath("/tmp/foo")
	if !isRelative(base, target) {
		t.Error("expected same path to be relative")
	}
	if isRelative(base, newLocalPath("/etc")) {
		t.Error("expected different path to not be relative")
	}
}
